FROM "Users" u, "Groups" g
WHERE (u."Username" = '5373346415' OR u."Email" = 'yunus@gmail.com') AND g."Name" = '2026 VİDEO'
  AND NOT EXISTS (
      SELECT 1 FROM "GroupMembers" gm 
      JOIN "Users" u2 ON gm."UserId" = u2."Id"
      JOIN "Groups" g2 ON gm."GroupId" = g2."Id"
      WHERE (u2."Username" = '5373346415' OR u2."Email" = 'yunus@gmail.com') AND g2."Name" = '2026 VİDEO'
  );
